contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 100 and 1 <= m <= 100 and 1 <= k <= 100",
      "description": "The dimensions n, m, and k of the Super Computer are within the specified range."
    },
    {
      "id": "P2",
      "expression": "len(layers) == n and all(len(layer) == m for layer in layers) and all(len(row) == k for layer in layers for row in layer)",
      "description": "The input contains exactly n layers, each with m rows and k columns."
    },
    {
      "id": "P3",
      "expression": "all(cell in {'0', '1'} for layer in layers for row in layer for cell in row)",
      "description": "Each cell in the layers is either '0' (malfunctioning) or '1' (working)."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "isinstance(return_value, int)",
      "description": "The output is a single integer."
    },
    {
      "id": "Q2",
      "expression": "0 <= return_value <= n * m * k",
      "description": "The number of critical CPUs is within the range of possible CPUs."
    },
